import{z as i,x as n,o as A,c as l,q as e,j as t,D as a,d as r,s,S as o}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"功耗管理","description":"","frontmatter":{"title":"功耗管理","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/emb-power-management.md","filePath":"cs/emb-power-management.md","lastUpdated":1791063341000}'),C={name:"cs/emb-power-management.md"};function d(p,E,m,c,D,_){const B=n("Mermaid");return A(),l("div",null,[E[2]||(E[2]=e('<h1 id="功耗管理" tabindex="-1">功耗管理 <a class="header-anchor" href="#功耗管理" aria-label="Permalink to &quot;功耗管理&quot;">​</a></h1><div class="epigraph"><p>电池设备的功耗账只有一个除法：容量除以寿命。账本上没有「差不多省点」，只有平均电流乘上小时数，一微安一微安地抠出来。</p><footer>—— 据各 MCU 数据手册的低功耗模式表；TI/ST 低功耗应用笔记整理</footer></div><p><a href="/cs/emb-rtos">上一课</a>的调度器让阻塞的任务不再烧 CPU，但「不参与调度」不等于「省电」：只要时钟还在跑、电压还在维持，电流就在流。电池供电的设备把这笔账推到极端——一颗 CR2032 纽扣电池标称 220 mAh，撑一年，平均电流必须压在 25 µA 附近，而 MCU 运行态动辄几毫安，差两个数量级。缺口不是优化代码，而是<strong>重新设计能量的时间结构</strong>：让芯片绝大部分时间待在深度睡眠里，醒来只做必要的事，做完立刻回去。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>平均电流 \\(\\bar{I}=\\sum_k I_k \\cdot d_k\\)，各模式电流乘驻留占比再求和。运行态 5 mA、睡眠 2 µA 的芯片，只要运行占比压到 0.5% 以下，平均电流就能进 25 µA 预算；占比一旦到 5%，平均 250 µA，电池半年见底。低功耗设计的全部工作因此是一张两列表：把每个模式的电流压到手册值，把高电流模式的驻留时间压到功能允许的最短。新手死在第二列：轮询式的「醒来—看一眼—没事—再睡」把驻留时间拖长一个量级，代码再省也救不回占空比。</p><p><span class="marginnote">把账代入具体数：CR2032 标称 220 mAh，一年 8760 小时，平均电流必须压在 220÷8760≈25 µA；若平均翻倍到 50 µA，同一颗电池半年就空。平均电流与寿命严格成反比——省电不是「差不多省点」，是每一微安都在换天数。</span></p><h3 id="睡眠模式的深度与代价" tabindex="-1">睡眠模式的深度与代价 <a class="header-anchor" href="#睡眠模式的深度与代价" aria-label="Permalink to &quot;睡眠模式的深度与代价&quot;">​</a></h3><p>睡眠不是一档而是一列。浅睡只停 CPU 核，外设与时钟照跑，唤醒几乎免费，但电流常在百微安级；停机模式切掉主时钟、保住 SRAM 与寄存器，电流进微安级，代价是唤醒后要等时钟源重新稳定；待机模式连 RAM 的电都断，只留备份寄存器，电流进亚微安级，代价是唤醒即复位——启动代码和运行时状态从头再来。每一档都在「省下的电流」与「唤醒的延迟和丢的状态」之间交易，选档的依据是两次活动之间隔多久、醒来要多快。</p>',8)),(A(),t(o,null,{default:a(()=>[s(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20WAKE%5B%22%E5%AE%9A%E6%97%B6%E5%99%A8%E6%88%96%E5%A4%96%E9%83%A8%E4%BA%8B%E4%BB%B6%E5%94%A4%E9%86%92%22%5D%20--%3E%20WORK%5B%22%E9%87%87%E6%A0%B7%E3%80%81%E8%AE%A1%E7%AE%97%E3%80%81%E7%BB%84%E5%8C%85%22%5D%0A%20%20WORK%20--%3E%20TX%5B%22%E4%B8%8A%E6%8A%A5%E6%95%B0%E6%8D%AE%EF%BC%8C%E7%AD%89%E5%BE%85%E5%AE%8C%E6%88%90%22%5D%0A%20%20TX%20--%3E%20GATE%5B%22%E5%85%B3%E5%A4%96%E8%AE%BE%E6%97%B6%E9%92%9F%EF%BC%8C%E9%85%8D%20GPIO%20%E9%98%B2%E6%BC%8F%E7%94%B5%22%5D%0A%20%20GATE%20--%3E%20ARM%5B%22%E5%AE%9A%E4%BD%8E%E5%8A%9F%E8%80%97%E5%AE%9A%E6%97%B6%E5%99%A8%E9%97%B9%E9%92%9F%22%5D%0A%20%20ARM%20--%3E%20DEEP%5B%22%E8%BF%9B%E5%85%A5%E5%81%9C%E6%9C%BA%E6%88%96%E5%BE%85%E6%9C%BA%22%5D%0A%20%20DEEP%20--%3E%20WAKE%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<p><span class="marginnote">深睡前 GPIO 是隐形漏电大户：浮空输入脚悬在中间电平，施密特触发器反复翻转，一个脚能漏几十微安。进停机前把不用的脚配成模拟输入或带上拉的输出——数据手册写了、代码评审最常漏的一条。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现按三条线走。第一，事件驱动重构：唤醒后一口气做完采样、计算、上报，再定好下一次闹钟进深睡，绝不在睡眠与运行间反复横跳——每次切换都有固定的能量税。第二，tickless 空闲：RTOS 的周期节拍本身就是功耗敌人，<a href="/cs/emb-rtos">实时操作系统 RTOS</a> 的阻塞模型配上 tickless，让内核在无任务可跑时停掉节拍、用低功耗定时器定下次唤醒点，空闲才真正变成深睡。第三，外设与时钟门控：不用的外设时钟逐个关掉，这延续了<a href="/cs/clock-gating-dvfs">时钟门控与 DVFS</a> 的机制——门控切断局部时钟树，动态功耗随 \\(CV^2f\\) 同步消失。测量用串接采样电阻加示波器或功耗分析仪：没有电流波形，一切「优化」都无法验收。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么深睡能省两个数量级？芯片电流是动态与静态两笔之和，主干课<a href="/cs/power-dynamic-static">功耗：动态与静态</a>讲过口径：动态随翻转率走，时钟一停即趋零；静态是漏电流，由工艺与温度决定，压不掉但可以少留「活着的电路」。睡眠档位本质是在逐块减少活着的那部分：浅睡停核，停机停时钟树，待机只留唤醒逻辑。唤醒延迟随之上升，因为恢复的层次更深——这决定了占空比有物理下限：每次唤醒的固定能量除以活动间隔，就是省不掉的那份平均电流。设计的目标不是「最深的睡」，而是让固定税被更长的睡眠摊薄。</p>',5)),(A(),t(o,null,{default:a(()=>[s(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20RUN%5B%22%E8%BF%90%E8%A1%8C%E6%80%81%EF%BC%9A%E5%87%A0%20mA%22%5D%20--%3E%7C%E5%8F%AA%E5%81%9C%20CPU%20%E6%A0%B8%7C%20SL%5B%22%E6%B5%85%E7%9D%A1%EF%BC%9A%E7%99%BE%20%C2%B5A%20%E7%BA%A7%EF%BC%8C%E6%97%B6%E9%92%9F%E5%A4%96%E8%AE%BE%E8%BF%98%E8%B7%91%22%5D%0A%20%20SL%20--%3E%7C%E5%86%8D%E5%88%87%E4%B8%BB%E6%97%B6%E9%92%9F%7C%20ST%5B%22%E5%81%9C%E6%9C%BA%EF%BC%9A%C2%B5A%20%E7%BA%A7%EF%BC%8CSRAM%20%E5%AF%84%E5%AD%98%E5%99%A8%E8%BF%98%E5%9C%A8%22%5D%0A%20%20ST%20--%3E%7C%E5%86%8D%E6%96%AD%20RAM%20%E4%BE%9B%E7%94%B5%7C%20SB%5B%22%E5%BE%85%E6%9C%BA%EF%BC%9A%E4%BA%9A%20%C2%B5A%20%E7%BA%A7%EF%BC%8C%E5%8F%AA%E5%89%A9%E5%A4%87%E4%BB%BD%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20SL%20--%3E%20C1%5B%22%E5%94%A4%E9%86%92%E5%87%A0%E4%B9%8E%E5%85%8D%E8%B4%B9%EF%BC%8C%E7%8A%B6%E6%80%81%E6%97%A0%E6%8D%9F%22%5D%0A%20%20ST%20--%3E%20C2%5B%22%E7%AD%89%E6%97%B6%E9%92%9F%E6%BA%90%E7%A8%B3%E5%AE%9A%EF%BC%8C%E7%8A%B6%E6%80%81%E4%BB%8D%E5%9C%A8%22%5D%0A%20%20SB%20--%3E%20C3%5B%22%E5%94%A4%E9%86%92%E5%8D%B3%E5%A4%8D%E4%BD%8D%EF%BC%8C%E8%BF%90%E8%A1%8C%E6%97%B6%E4%BB%8E%E5%A4%B4%E5%86%8D%E6%9D%A5%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p><span class="marginnote">可以把占空比想象成灯塔：灯 99% 的时间熄着，船靠近才亮几秒。省电的关键从来不是让亮的那一瞬更暗，而是让「亮」的占比尽量小——亮灯时的电流再省，也不如把亮灯时间从 1% 压到 0.1% 来得狠。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课写的是通用 MCU 的功耗工程，不写三块。射频的功耗协议栈——BLE 的连接间隔、LoRa 的扩频预算——是无线的课，本课只负责让 CPU 与外设不白耗。DVFS 连续调档是应用处理器的玩法，MCU 上更常见的是几个离散电压档，主干课 DVFS 的机制照用，形态不同。电池也是边界：锂纽扣电池有自放电与脉冲电流限制，账要按真实放电曲线算，不能只拿标称容量除。最后一条纪律：功耗验收用整机静态电流加动态波形两个数，只报「睡眠 2 µA」不报驻留占比的，账都算不平。</p><p><span class="marginnote">初学者容易以为「代码里写了进停机模式」就等于省电；浅睡只停 CPU 核，某个外设时钟忘了关、一个 GPIO 浮空，电流就还停在几百 µA。验收只认一个证据：功耗分析仪上的电流波形台阶，不看代码写了哪一档。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>功耗设计是占空比设计：平均电流等于各模式电流乘驻留占比，账要一列一列算。</li><li>睡眠按深浅选档，每深一档省电流、丢状态、长唤醒，选档依据是间隔与实时要求。</li><li>事件驱动加 tickless 把空闲真正变成深睡；GPIO 漏电与外设时钟是最常见的暗账。</li><li>唤醒的固定能量税除以活动间隔，是平均电流省不掉的物理下限。</li><li>出处：各 MCU 数据手册与低功耗应用笔记；据本栏 clock-gating-dvfs、power-dynamic-static 两课的功耗口径整理。</li></ul>',6))])}const F=i(C,[["render",d]]);export{T as __pageData,F as default};
